_TERMINATOR = b"<|END|>"
_SUCCESS = "<|SUCCESS|>"

class _SimpleResponse:
    """requests.Response互換の最小レスポンスオブジェクト"""
    __slots__ = ('status_code', 'text', '_content')
    def __init__(self, status_code, text):
        self.status_code = status_code
        self.text = text
        self._content = text.encode('utf-8') if isinstance(text, str) else text
    def json(self):
        # ソケットプロトコルは生の数値を返す（JSON辞書ではない）
        # 呼び出し元は int(v["value"]) if isinstance(v, dict) else int(v) で処理
        try:
            return int(self.text)
        except (ValueError, TypeError):
            import json as _json
            return _json.loads(self.text)

class SimpleHTTPClient:
    """mGBA-httpソケットプロトコルクライアント（requests.Session互換API）
    ★ v10.9z248: HTTP→ソケットプロトコル変換
    URL形式のAPIコールをソケットコマンドに変換して送信:
      GET  http://host:port/core/read8?address=0x... → "core.read8,0x...<|END|>"
      POST http://host:port/mgba-http/button/hold?button=A&duration=2
           → "mgba-http.button.hold,A,2<|END|>"
    """
    _error_count = 0
    _total_requests = 0

    @staticmethod
    def _url_to_socket_cmd(url, params=None):
        """HTTP URL → ソケットコマンド変換"""
        if params:
            url = url + "?" + urllib.parse.urlencode(params)
        # URLパース: http://127.0.0.1:8888/core/read8?address=0x02000000
        _parts = url.split("//", 1)[1]  # 127.0.0.1:8888/core/read8?...
        _host_port, _path = _parts.split("/", 1)
        _host, _port = _host_port.split(":")
        # パスとクエリパラメータを分離
        if "?" in _path:
            _path_part, _query = _path.split("?", 1)
        else:
            _path_part, _query = _path, ""
        # パスをドット区切りコマンドに変換: core/read8 → core.read8
        # mgba-http/button/hold → mgba-http.button.hold
        # /mgba-http/1/core/read8 のような形式も処理
        _path_part = _path_part.strip("/")
        if _path_part.startswith("mgba-http/1/"):
            _path_part = _path_part[len("mgba-http/1/"):]
        _cmd = _path_part.replace("/", ".")
        # クエリパラメータを値リストに変換
        _values = []
        if _query:
            _qp = urllib.parse.parse_qs(_query, keep_blank_values=True)
            # パラメータ順序: address, length, value, button, duration, slot, flags
            for key in ("address", "length", "value", "button", "duration",
                        "slot", "flags", "path"):
                if key in _qp:
                    _values.append(_qp[key][0])
        # コマンド組立: "core.read8,0x02000000"
        if _values:
            _msg = _cmd + "," + ",".join(_values)
        else:
            _msg = _cmd
        return _host, int(_port), _msg

    def _do_request(self, method, url, params=None, timeout=None):
        SimpleHTTPClient._total_requests += 1
        _timeout = timeout[1] if isinstance(timeout, tuple) else (timeout or 1.5)
        try:
            _host, _port, _cmd = self._url_to_socket_cmd(url, params)
            sock = _socket.socket(_socket.AF_INET, _socket.SOCK_STREAM)
            sock.settimeout(_timeout)
            try:
                sock.connect((_host, _port))
                sock.sendall(_cmd.encode('utf-8') + _TERMINATOR)
                # レスポンス受信（<|END|>まで）
                _buf = b""
                while _TERMINATOR not in _buf:
                    _chunk = sock.recv(4096)
                    if not _chunk:
                        break
                    _buf += _chunk
                _resp = _buf.split(_TERMINATOR)[0].decode('utf-8')
                # <|SUCCESS|> → 空レスポンス扱い
                if _resp == _SUCCESS:
                    return _SimpleResponse(200, "0")
                return _SimpleResponse(200, _resp)
            finally:
                sock.close()
        except Exception:
            SimpleHTTPClient._error_count += 1
            return _SimpleResponse(503, "0")

    def get(self, url, params=None, timeout=None):
        return self._do_request('GET', url, params, timeout)

    def post(self, url, params=None, timeout=None, **kwargs):
        return self._do_request('POST', url, params, timeout)

    def close(self):
        pass

    def mount(self, *args, **kwargs):
        pass

