    _wd_started = False

    @classmethod
    def _start_watchdog(cls):
        """10秒以上step()が完了しない場合にログ出力するウォッチドッグスレッド"""
        if cls._wd_started:
            return
        cls._wd_started = True
        def _watchdog():
            while True:
                time.sleep(10)
                _elapsed = time.time() - cls._wd_last_step_time
                if cls._wd_last_step_time > 0 and _elapsed > 10:
                    print(f"  [WATCHDOG] Step hung! port={cls._wd_last_port}"
                          f" step={cls._wd_last_step} elapsed={_elapsed:.0f}s",
                          flush=True)
        _t = threading.Thread(target=_watchdog, daemon=True)
        _t.start()

