        # v261hr-C REVERTED: Rusturf gating 削除
        if (self._cached_map_group == 0 and self._cached_map_num == 19
                and getattr(self, '_devon_event_done', False)
                and self._cached_badges < 2
                and self._battle_cycle_counter == 0):
            _r104_x, _r104_y = self.prev_x, self.prev_y
            # cottage approach zone: x=17 column の y=45-50 (warp entry from (24,11))
