                                self._nav_step = 0
                                self._nav_target = "deep_explore"
                                self._nav_path_map = _cur_map
                                _bfs_nav_path_found = True
                                print(f"  [DeepExplore] R102 forced west "
                                      f"from X={self.prev_x}")
